<script setup lang="ts">
import {ref,watch} from 'vue';import {api} from '../api';import Modal from './Modal.vue';import type {WorkTab} from '../stores';
const props=defineProps<{record:any;tab:WorkTab}>(),emit=defineEmits<{cancel:[];saved:[]}>(),date=ref(''),preview=ref<any>(null),error=ref(''),loading=ref(false);
watch(date,()=>{preview.value=null;error.value='';});
function cancel(){if(!loading.value&&!props.tab.busy)emit('cancel');}
async function inspect(){loading.value=true;error.value='';preview.value=null;try{preview.value=await api('transfers/preview',{method:'POST',body:JSON.stringify({id:props.record.id,effective_date:date.value})});}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function save(){if(!preview.value?.canSubmit||props.tab.busy)return;props.tab.busy=true;error.value='';try{await api('transfers/confirm',{method:'POST',body:JSON.stringify({id:props.record.id,effective_date:date.value,version:preview.value.version})});emit('saved');}catch(e){error.value=(e as Error).message;preview.value=null;}finally{props.tab.busy=false;}}
</script>
<template><Modal title="確認調店生效" @cancel="cancel"><p><strong>{{record.employee_code}} {{record.employee_name}}</strong></p><p>{{record.from_store?.store_name}} → {{record.to_store?.store_name}}</p><p>可填寫過去、今天或未來的生效日期。確認後立即更新主檔與下方月資料，並記錄指定生效日，不會等到當天才執行。</p><form @submit.prevent="inspect"><label>生效日期<input v-model="date" type="date" min="1912-01-01" required :disabled="loading||tab.busy"></label><button type="submit" :disabled="loading||tab.busy">{{loading?'正在核對…':'核對調店影響'}}</button></form><p v-if="error" role="alert" class="notice error">{{error}}</p>
<template v-if="preview"><ul v-if="preview.conflicts.length" class="notice error" role="alert"><li v-for="item in preview.conflicts" :key="item">{{item}}</li></ul><template v-else><p>員工主檔將由原門市轉至新門市，並建立調店異動紀錄。</p><div v-if="preview.changes.length" class="module-table"><table><thead><tr><th>月份</th><th>門市</th><th>處理</th><th>天數</th></tr></thead><tbody><tr v-for="(change,i) in preview.changes" :key="i"><td>{{change.year_month}}</td><td>{{change.store_id===record.from_store_id?'調出門市':'調入門市'}}</td><td>{{change.operation==='insert'?'新增':'更新'}}</td><td>{{change.work_days}} / {{change.total_days_in_month}}</td></tr></tbody></table></div><p v-else>目前沒有已初始化、需要同步的人員月資料。</p><p>確認後，上述資料會一起儲存。</p></template></template>
<div class="dialog-actions"><button :disabled="loading||tab.busy" @click="cancel">返回</button><button v-if="preview?.canSubmit" class="primary" :disabled="tab.busy||loading" @click="save">{{tab.busy?'正在確認…':'確認生效'}}</button></div></Modal></template>
<style scoped>form{display:flex;gap:12px;align-items:end;flex-wrap:wrap}label{display:grid;gap:8px}.module-table{max-height:300px;overflow:auto}.module-table table{min-width:0;width:100%}.module-table th,.module-table td{padding:10px 8px;white-space:normal}li+li{margin-top:8px}</style>
